param([string]$CaseId='all')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78NativeFunctionalResults";New-Item -ItemType Directory $out -Force|Out-Null;$env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";$env:TEMP="$out\temp";$env:TMP=$env:TEMP;New-Item -ItemType Directory $env:TEMP -Force|Out-Null
function Upload($p,$n){Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null}
try{
 $m=(Invoke-WebRequest -UseBasicParsing "$base/m78-native-functional-manifest.json").Content|ConvertFrom-Json;if((Get-FileHash $m.libraryPath).Hash.ToLower() -ne $m.librarySHA256){throw 'Frozen final production archive changed'};$cases=@($m.cases|Where-Object {$CaseId -eq 'all' -or $_.id -eq $CaseId});if(!$cases.Count){throw 'No explicit prepared case'}
 foreach($case in $cases){
  if((Get-PSDrive C).Free -lt 24MB){throw ('Insufficient bounded headroom before '+$case.id)};$restore=!(Test-Path $case.path)
  foreach($row in $case.compiles){if((Get-FileHash $row.source).Hash.ToLower() -ne $row.sourceSHA256){throw 'Original compiled source identity changed'}}
  if($restore){Invoke-WebRequest -UseBasicParsing "$base/$($case.downloadName)" -OutFile $case.path};if((Get-Item $case.path).Length -ne $case.bytes -or (Get-FileHash $case.path).Hash.ToLower() -ne $case.sha256){throw 'Exact independently archived executable mismatch'}
  foreach($run in $case.runs){
   $name="m78-native-functional-$($run.id)";if(Test-Path "$out\$name.json"){throw 'Preserve preceding functional receipt'}
   if($run.copyExactColdFrom){$dest=$run.arguments[0];if(Test-Path $dest){throw 'Preserve exact cold input copy'};if((Get-FileHash "$($run.copyExactColdFrom)\slots\m77.save").Hash.ToLower() -ne $run.expectedSaveSHA256){throw 'Original failed a106 input changed'};New-Item -ItemType Directory $dest|Out-Null;Copy-Item "$($run.copyExactColdFrom)\project","$($run.copyExactColdFrom)\slots" $dest -Recurse;if((Get-FileHash "$dest\slots\m77.save").Hash.ToLower() -ne $run.expectedSaveSHA256){throw 'Exact copied cold input mismatch'}}
   $options=@{FilePath=$case.path;WorkingDirectory="$root\Source";PassThru=$true;RedirectStandardOutput="$out\$name.stdout.log";RedirectStandardError="$out\$name.stderr.log"};if($run.arguments.Count){$options.ArgumentList=@($run.arguments)};$watch=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process @options;[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;$exit='owned case timed out'}else{$p.Refresh();$exit=$p.ExitCode};$watch.Stop();@{scope='Fresh original native functional execution on unchanged final archive; original inputs/timesteps/thresholds retained. No build. VM timing is descriptive only.';case=$case.id;run=$run.id;exitCode=$exit;seconds=$watch.Elapsed.TotalSeconds;executable=$case.path;executableSHA256=$case.sha256;librarySHA256=$m.librarySHA256;arguments=@($run.arguments);expectedSaveSHA256=$run.expectedSaveSHA256;environment=@{GALLIUM_DRIVER=$env:GALLIUM_DRIVER;JUDAS_ENGINE_ROOT=$env:JUDAS_ENGINE_ROOT};freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 6|Set-Content "$out\$name.json" -Encoding UTF8;Upload "$out\$name.stdout.log" "$name.stdout.log";Upload "$out\$name.stderr.log" "$name.stderr.log";Upload "$out\$name.json" "$name.json"
  }
  if($restore){if((Get-Item $case.path).Length -ne $case.bytes -or (Get-FileHash $case.path).Hash.ToLower() -ne $case.sha256){throw 'Owned restored copy changed; preserve'};if(@(Get-Process|Where-Object {$_.Path -eq $case.path}).Count){throw 'Owned restored copy still running'};Remove-Item -LiteralPath $case.path;@{scope='Only exact newly restored owned executable copy removed; independently verified host bytes retained, source/library/results untouched';path=$case.path;sha256=$case.sha256;bytes=$case.bytes;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 4|Set-Content "$out\m78-native-functional-$($case.id)-restored-copy-cleanup.json" -Encoding UTF8;Upload "$out\m78-native-functional-$($case.id)-restored-copy-cleanup.json" "m78-native-functional-$($case.id)-restored-copy-cleanup.json"}
 }
}catch{$name="m78-native-functional-$CaseId-error.txt";[string]$_.Exception.Message|Set-Content "$out\$name";Upload "$out\$name" $name;exit 1}
